var MEMBERS_PATH = '/lvr_rewards';
// MEMBER DATA PROTECTION (docs/key-integration/MEMBER_DATA_PLAN.md): after the cut-over, phone, email, birthday and the link token live in lvr_member_private/<token>
// (token = the key, value has memberKey). These helpers put them back onto the member records so the rest of this page keeps working in BOTH layouts.
function privIndex() {
  return fbGet('/lvr_member_private').then(function(p){ var by = {}; Object.keys(p && typeof p === 'object' && !p.error ? p : {}).forEach(function(t){ var v = p[t] || {}; if (v.memberKey) by[v.memberKey] = Object.assign({ token: t }, v); }); return by; }).catch(function(){ return {}; });
}
function fbGetMembers() {
  return Promise.all([fbGet(MEMBERS_PATH), privIndex()]).then(function(r){
    var m = r[0] && typeof r[0] === 'object' ? r[0] : r[0], by = r[1];
    if (m && typeof m === 'object') Object.keys(by).forEach(function(k){ if (m[k] && typeof m[k] === 'object') ['phone', 'email', 'birthday', 'anniversary', 'token'].forEach(function(f){ if (m[k][f] == null && by[k][f] != null) m[k][f] = by[k][f]; }); });
    return m;
  });
}
function fbGetToken(k) {
  return fbGet(MEMBERS_PATH + '/' + encodeURIComponent(k) + '/token').then(function(t){ if (t) return t; return privIndex().then(function(by){ return by[k] && by[k].token || null; }); });
}
